import json

def gsl_poly_complex_solve(coefficients):
    # Load the necessary dynamic libraries
    try:
        libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        print(f"Error loading GSL libraries: {e}")
        return json.dumps({"error": "Failed to load GSL libraries"})

    # Define the function signature and parameter list for gsl_poly_complex_solve
    gsl_poly_complex_solve_ptr = libgsl.gsl_poly_complex_solve
    gsl_poly_complex_solve_ptr.argtypes = [POINTER(ctypes.c_double), ctypes.c_size_t, POINTER(GSLPolyComplexWorkspace)]
    gsl_poly_complex_solve_ptr.restype = ctypes.POINTER(GSLPolyComplexWorkspace)

    # Create a workspace for the complex roots
    workspace = GSLPolyComplexWorkspace()

    # Call the C function to compute the complex roots
    try:
        gsl_poly_complex_solve_ptr(coefficients, len(coefficients), byref(workspace))
    except ValueError as e:
        print(f"Error calling gsl_poly_complex_solve: {e}")
        return json.dumps({"error": "Failed to compute complex roots"})

    # Extract the complex roots from the workspace
    roots = []
    for i in range(workspace.nroots):
        root = (workspace.roots[i].real, workspace.roots[i].imag)
        roots.append(root)

    # Return the complex roots as a JSON object
    return json.dumps({"Candidate_solution": str(roots)})

