class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = (ctypes.c_double * (rows * cols))()

    @property
    def size(self):
        return self.rows, self.cols

    def __getitem__(self, index):
        if isinstance(index, int):
            return GSLVectorView(self, index)
        elif isinstance(index, tuple):
            row, col = index
            if not (0 <= row < self.rows and 0 <= col < self.cols):
                raise IndexError("Index out of range")
            return self.data[row * self.cols + col]
        else:
            raise TypeError("Invalid index type")

class GSLVectorView:
    def __init__(self, matrix, row_index):
        self.matrix = matrix
        self.row_index = row_index

    @property
    def size(self):
        return self.matrix.cols

    def __getitem__(self, index):
        if isinstance(index, int):
            return self.matrix.data[self.row_index * self.matrix.cols + index]
        else:
            raise TypeError("Invalid index type")

# Define the GSL vector class and its methods
class GSLVector:
    def __init__(self, size):
        self.size = size
        self.data = (ctypes.c_double * size)()

# Define the 'extract_row' function
def extract_row(matrix, row_index):
    if not isinstance(matrix, GSLMatrix):
        raise TypeError("Invalid matrix type")
    if not isinstance(row_index, int):
        raise TypeError("Invalid row index type")
    if row_index < 0 or row_index >= matrix.rows:
        raise IndexError("Row index out of range")

    # Create a new GSL vector object to store the extracted row
    vec = GSLVector(matrix.cols)

    # Extract the specified row from the given matrix and copy it into the new vector
    for i in range(vec.size):
        vec[i] = matrix[row_index, i]

    return vec

