    return GSLMatrix(size1, size2, data)

def gsl_matrix_to_numpy(gsl_matrix):
    numpy_matrix = [[0.0 for _ in range(gsl_matrix.size2)] for _ in range(gsl_matrix.size1)]
    for i in range(gsl_matrix.size1):
        for j in range(gsl_matrix.size2):
            numpy_matrix[i][j] = gsl_matrix.data[i + j * gsl_matrix.size1]
    return numpy_matrix

