from ctypes import CDLL, POINTER, Structure, byref, cast, c_float, c_int, c_uint, pointer, addressof

class GSLMatrix(Structure):
    _fields_ = [("data", POINTER(c_float)), ("size1", c_int), ("size2", c_int)]

    def __init__(self, rows, cols):
        self._allocate()
        self.rows = rows
        self.cols = cols

    def _allocate(self):
        self.data = cast((c_float * (self.rows * self.cols))(), POINTER(c_float))

    def free(self):
        if self.data:
            self.data.contents = None

    def to_numpy(self):
        return np.array(self.data[:self.size1*self.size2]).reshape((self.rows, self.cols))

def list_to_ctypes_matrix(lst):
    rows = len(lst)
    cols = len(lst[0]) if lst else 0
    mat = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            mat[i, j] = lst[i][j]
    return mat

