class GslSfResult:
    def __init__(self, value=0.0, error=0.0):
        self.value = value
        self.error = error

    def __str__(self):
        return "({}, {})".format(self.value, self.error)

def compute_mathieu_mc(kind, order, qq, zz):
    if kind not in [1, 2]:
        raise ValueError("Invalid value for 'kind'. Must be either 1 or 2.")
    if order < 0:
        raise ValueError("Invalid value for 'order'. Must be non-negative.")
    if qq <= 0.0:
        raise ValueError("Invalid value for 'qq'. Must be greater than 0.")
    if zz <= 0.0:
        raise ValueError("Invalid value for 'zz'. Must be greater than 0.")

    try:
        gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define the C function prototype and its parameters
        compute_mathieu_mc_prototype = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_int, ctypes.c_int, ctypes.c_double, ctypes.c_double)(
            "gsl_sf_mathieu_Mc_e")
        compute_mathieu_mc_parameters = [kind, order, qq, zz]

        # Call the C function and get the result
        result = compute_mathieu_mc_prototype(*compute_mathieu_mc_parameters)
        error = fabs(result - gsl.gsl_sf_mathieu_Mc_e(kind, order, qq, zz))

    except OSError as e:
        raise ValueError("Failed to load the GSL library.") from e

    return GslSfResult(value=result, error=error)

