    class GSLFunction(object):
        def __init__(self, func):
            self.func = func

        def wrapped_func(self, x):
            return self.func(x)

    wrapped_func = GSLFunction(wrapped_func).wrapped_func

    # Perform the minimization using Brent's method
    result = gsl.brent_iterate(
