class GSLVector:
    def __init__(self, data):
        self.data = data

# Create a GSL vector and populate it with data
def create_gsl_vector(data):
    # Define the size of the vector
    n = len(data)

    # Allocate memory for the vector
    vector = gsl.malloc(n * ctypes.sizeof(ctypes.c_double))

    # Copy the data into the vector
    for i in range(n):
        vector[i] = data[i]

    return GSLVector(vector)

# Call the 'gsl_vector_reverse' function to reverse the elements of the vector
def gsl_vector_reverse(vector):
    # Define the size of the vector
    n = len(vector.data)

    # Allocate memory for the reversed vector
    rev_vector = gsl.malloc(n * ctypes.sizeof(ctypes.c_double))

    # Reverse the elements of the vector
    for i in range(n):
        rev_vector[i] = vector.data[n - 1 - i]

    return GSLVector(rev_vector)

# Verify the correctness of the reversal by comparing the reversed vector to the expected result
def verify_reversal(vector, expected):
    # Check that the vectors have the same size
    if len(vector.data) != len(expected):
        raise ValueError("The vectors must have the same size")

    # Compare the elements of the reversed vector with the expected result
    for i in range(len(vector.data)):
        if vector.data[i] != expected[i]:
            return False

    return True

